<script setup lang="ts">
import { Plus, Search } from '@element-plus/icons-vue'; import { computed, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus';
const query=ref(''), type=ref('ALL'), dialog=ref(false); const form=reactive({title:'',summary:'',type:'业务规则'});
const cards=ref([{title:'订单超时关闭规则',type:'业务规则',summary:'待支付订单超过 30 分钟后自动关闭，并释放预占库存。',source:'OrderTimeoutService.java',updated:'今天 14:46',tags:['订单','库存']},{title:'库存释放幂等策略',type:'技术决策',summary:'使用订单号与 SKU 作为幂等键，重复请求不会造成库存累加。',source:'InventoryService.java',updated:'昨天 18:10',tags:['库存','幂等']},{title:'支付事件消费约定',type:'接口约定',summary:'支付域通过事件总线发布支付状态，订单域负责最终状态收敛。',source:'PaymentListener.java',updated:'07-17',tags:['支付','事件']},{title:'订单模块概览',type:'模块说明',summary:'订单模块负责创建、支付状态、关闭与售后入口编排。',source:'order-domain',updated:'07-15',tags:['架构']},{title:'异常重试规范',type:'技术决策',summary:'外部服务调用采用指数退避，最多重试三次并进入死信队列。',source:'RetryPolicy.java',updated:'07-12',tags:['可靠性']},{title:'网关鉴权流程',type:'模块说明',summary:'请求经过令牌校验、权限匹配和租户上下文注入。',source:'AuthFilter.java',updated:'07-10',tags:['网关','安全']}]);
const rows=computed(()=>cards.value.filter(x=>(!query.value||x.title.includes(query.value)||x.summary.includes(query.value))&&(type.value==='ALL'||x.type===type.value))); function add(){if(!form.title)return ElMessage.warning('请输入标题');cards.value.unshift({...form,source:'手动创建',updated:'刚刚',tags:['自定义']});dialog.value=false;ElMessage.success('知识卡片已创建')}
</script>
<template><section class="page"><div class="summary-strip"><div><b>{{cards.length}}</b><span>知识卡片</span></div><div><b>4</b><span>自动生成</span></div><div><b>2</b><span>人工维护</span></div><div><b>5</b><span>本周更新</span></div></div><div class="surface"><div class="toolbar"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索标题或内容"/><el-select v-model="type"><el-option label="全部类型" value="ALL"/><el-option v-for="x in ['业务规则','技术决策','接口约定','模块说明']" :key="x" :label="x" :value="x"/></el-select><span class="spacer"/><el-button type="primary" :icon="Plus" @click="dialog=true">新建卡片</el-button></div><div class="knowledge-grid"><article v-for="card in rows" :key="card.title" class="knowledge-card"><header><el-tag effect="plain">{{card.type}}</el-tag><button>•••</button></header><h3>{{card.title}}</h3><p>{{card.summary}}</p><div class="tags"><span v-for="tag in card.tags" :key="tag"># {{tag}}</span></div><footer><span class="mono">{{card.source}}</span><time>{{card.updated}}</time></footer></article></div></div><el-dialog v-model="dialog" title="新建知识卡片" width="500"><el-form label-position="top"><el-form-item label="标题" required><el-input v-model="form.title"/></el-form-item><el-form-item label="类型"><el-select v-model="form.type" style="width:100%"><el-option v-for="x in ['业务规则','技术决策','接口约定','模块说明']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="摘要"><el-input v-model="form.summary" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="add">创建</el-button></template></el-dialog></section></template>
